from pathlib import Path
import json, re, html

ROOT = Path(__file__).resolve().parents[1]
esc = html.escape
records = json.loads((ROOT / "catalogue-sample.json").read_text())
records = {r["id"]: r for r in records}
observations = json.loads((ROOT / "observations.json").read_text())["recordings"]
frames = json.loads((ROOT / "frame-manifest.json").read_text())
frames = {r["id"]: r for r in frames}
style = re.search(
    r"<style>(.*?)</style>", (ROOT.parent / "curling-landscape.html").read_text(), re.S
).group(1)
style += """
.audit-hero{display:grid;grid-template-columns:1fr 1fr;gap:28px;align-items:center}.audit-hero img{width:100%;border-radius:5px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:30px 0}.stat{border-top:2px solid var(--teal);padding:15px 0}.stat strong{display:block;font:38px Georgia,serif}.stat span{font-size:13px;color:var(--muted)}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.filters button{padding:9px 13px;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:4px;font-size:13px}.filters button[aria-pressed=true]{background:var(--ink);color:white}.record{margin:0 0 28px;background:var(--card);border:1px solid var(--line);border-radius:6px;overflow:hidden}.record-head{padding:25px 28px 15px}.record h3{font:27px Georgia,serif}.record-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:25px;padding:0 28px 25px}.record-grid figure{margin:0}.record-grid img{width:100%;height:auto;border-radius:3px}.record p{font-size:14px;margin-bottom:13px}.record figcaption{font-size:12px;color:var(--muted);margin-top:8px}.record details{margin:0 28px;border-top:1px solid var(--line);border-bottom:0}.record details:last-child{margin-bottom:16px}.contact{display:block;max-width:100%;width:800px;margin:18px auto}.thumb-links{display:flex;flex-wrap:wrap;gap:9px;font-size:13px;margin:16px 0}.badge{font-size:11px;display:inline-block;background:#e9eee8;padding:3px 8px;border-radius:3px;margin:0 5px 5px 0}.warning{background:#f8e9df;border-color:#bc6244}.record[hidden]{display:none}.status{font-size:13px;color:var(--muted)}.architecture{background:var(--ink);color:white;border-radius:5px;padding:25px;font-size:17px;line-height:2}.architecture span{color:#e6b963}.checklist li{margin-bottom:10px}.wide-figure{margin:22px 0}.wide-figure img{max-width:100%;border-radius:4px}.wide-figure figcaption{font-size:13px;color:var(--muted)}@media(max-width:760px){.audit-hero,.record-grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.record-grid{padding:0 18px 20px}.record-head{padding:20px 18px 12px}.record details{margin:0 18px}.audit-hero img{max-height:260px;object-fit:cover}}@media print{.filters{display:none}.record{break-inside:auto}.record-grid{break-inside:avoid}details img{max-height:600px;object-fit:contain}}
"""


def stamp(s):
    return (
        f"{s // 3600:d}:{s % 3600 // 60:02d}:{s % 60:02d}"
        if s >= 3600
        else f"{s // 60:02d}:{s % 60:02d}"
    )


def card(o):
    vid = o["id"]
    r = records[vid]
    f = frames[vid]
    ts = o["hero_s"]
    still = f"frames/{vid}/{ts:05d}.jpg"
    assert (ROOT / still).exists()
    rawtitle = esc(r["title"])
    rows = ", ".join(x["sheet_row"] for x in r["catalogue_rows"])
    tags = f'<span class="badge">{f["width"]} × {f["height"]} sampled</span><span class="badge">{stamp(r["duration_s"])} recording</span><span class="badge">Sheet rows {rows}</span>'
    links = "".join(
        f'<a href="{esc(x["file"])}">{stamp(x["requested_timestamp_s"])}</a>'
        for x in f["frames"]
        if x["file"]
    )
    temporal = ""
    if o["temporal"]:
        temporal = f'<details><summary>12-second temporal probe</summary><p>{esc(o["temporal"])}</p><a href="contact-sheets/{vid}-temporal.jpg"><img class="contact" loading="lazy" src="contact-sheets/{vid}-temporal.jpg" alt="Six successive samples from a 12-second window of {esc(o["label"])}"></a></details>'
    return f'''<article class="record" data-family="{o["family"]}"><div class="record-head"><span class="eyebrow">{esc(o["family"])} / {esc(r["uploader"])}</span><h3>{esc(o["label"])}</h3>{tags}</div><div class="record-grid"><figure><a href="{still}"><img loading="lazy" src="{still}" alt="Sample at {stamp(ts)} from {esc(o["label"])}"></a><figcaption>Evidence at {stamp(ts)} · <a href="{r["url"]}&t={ts}s">Open source at this time ↗</a><br>Retrieved title: {rawtitle}<br>Highest offered height: {r["max_available_height"]}p; sample uses format {f["format_id"]}.</figcaption></figure><div><p><strong>Observed.</strong> {esc(o["observed"])}</p><p><strong>Opportunity.</strong> {esc(o["opportunity"])}</p><p><strong>Difficulty.</strong> {esc(o["difficulty"])}</p><p><strong>Coverage.</strong> {esc(o["completeness"])}</p><p><strong>Decision.</strong> {esc(o["next"])}</p></div></div><details><summary>Inspect all eight systematic samples</summary><div class="thumb-links">{links}</div><a href="contact-sheets/{vid}.jpg"><img class="contact" loading="lazy" src="contact-sheets/{vid}.jpg" alt="Eight-frame contact sheet for {esc(o["label"])}"></a></details>{temporal}</article>'''


body = (
    """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>What the footage actually contains · Curling input audit</title><style>"""
    + style
    + """</style></head><body><a class="skip" href="#findings">Skip to findings</a><nav aria-label="Audit navigation"><div class="wrap nav-inner"><a class="brand" href="#top">CURLING / FOOTAGE AUDIT</a><div class="nav-links"><a href="#findings">Findings</a><a href="#recordings">Visual evidence</a><a href="#plan">Build decisions</a><a href="#method">Method &amp; files</a></div></div></nav><main class="wrap" id="top"><header><div class="audit-hero"><div><div class="eyebrow">Customer footage · First reconnaissance</div><h1>One upload.<br><em>Many views.</em></h1><p class="lead">The real input is often a composite of cameras, ends and even matches. Reliable reconstruction starts by separating those views.</p><p class="metadata">23 September 2026 · Eight recordings · Visual evidence, not a detector benchmark</p></div><figure class="wide-figure"><img src="frames/dcb_DCtBW-4/08322.jpg" alt="Four-panel wheelchair curling recording"><figcaption>GSOC recording at 2:18:42: four panels and two matches. <a href="https://www.youtube.com/watch?v=dcb_DCtBW-4&t=8322s">Source ↗</a></figcaption></figure></div></header><div class="verdict"><div class="eyebrow">The main finding</div><p><strong>Split-screen support belongs in the core product.</strong> Seven of eight sampled recordings contain composite views. A single whole-frame calibration and one-game-per-video assumption would fail on this collection.</p></div><div class="stats"><div class="stat"><strong>317</strong><span>catalogue entries, first tab</span></div><div class="stat"><strong>8</strong><span>recordings visually sampled</span></div><div class="stat"><strong>64 + 24</strong><span>systematic frames + temporal frames</span></div><div class="stat"><strong>18.25 h</strong><span>combined recording duration—not time watched</span></div></div>
<section id="findings"><div class="section-head"><span class="number">01</span><h2>What changed after looking.</h2></div><div class="grid"><article class="card"><span class="tag">Input architecture</span><h3>Panels are not matches.</h3><p>A panel can contain multiple sheets; two panels can show opposite ends of one sheet; four panels can cover two matches. Richmond also changes the view within panels across sampled times.</p><p class="take">Represent recording → panel/view interval → sheet/end association → match. Calibrate each camera view independently.</p></article><article class="card"><span class="tag amber">Image quality</span><h3>Four recordings offer only 480p.</h3><p>The 2022 team and training sources often split that small canvas again. Stones at the far end are much smaller than near-house stones. Upscaling cannot recover absent image detail.</p><p class="take">Measure stone size and positional uncertainty per view. Start the split-view prototype on the clearer 1080p Canada–Korea recording.</p></article><article class="card"><span class="tag">Unexpected opportunity</span><h3>Small overhead insets may help.</h3><p>Leduc's main oblique views include overhead house insets. They are promising for house geometry, but crop guard areas and can duplicate stones already visible in the main view.</p><p class="take">Treat the inset as a separate camera with explicit association; evaluate native 1440p before judging its precision.</p></article><article class="card warning"><span class="tag amber">Metadata conflict</span><h3>Verify the teams before exporting.</h3><p>The GSOC title/catalogue says CAN Red–GBR and CAN White–ITA. On-screen labels in sampled frames say CAN R–ITA and CAN W–GBR. The audit cannot establish which is correct.</p><p class="take">Flag the conflict. Preserve observations, but do not silently attach them to validated team identities.</p></article></div><div class="note"><strong>Wheelchair footage must drive the design.</strong> Wheelchair players are visible in all eight sampled recordings. Occlusion around the house is a recurring issue. The earlier 2018 Olympic mixed-doubles pilot remains a geometry experiment; it does not establish performance on this customer collection.</div></section>
<section id="recordings"><div class="section-head"><span class="number">02</span><h2>Inspect the actual recordings.</h2></div><p class="intro">Each card separates observed evidence from engineering judgement. Open the contact sheets to see all systematic samples, not only the featured frame. Source links jump to the requested sample time.</p><div class="filters" role="group" aria-label="Filter recordings"><button aria-pressed="true" data-filter="all">All recordings</button><button aria-pressed="false" data-filter="broadcast">Broadcast</button><button aria-pressed="false" data-filter="split">Two-view single match</button><button aria-pressed="false" data-filter="inset">Overhead insets</button><button aria-pressed="false" data-filter="multi">Multiple sheets / matches</button></div><p id="filter-status" class="status" aria-live="polite">Showing 8 recordings</p>"""
)
body += "".join(card(o) for o in observations)
body += """</section><section><div class="section-head"><span class="number">03</span><h2>Access and catalogue quality.</h2></div><div class="table-wrap"><table><thead><tr><th>Finding</th><th>Evidence</th><th>Consequence</th></tr></thead><tbody><tr><td>Repeated recording links</td><td>27 repeated target groups. Some correspond to distinct matches or playlist contexts rather than accidental duplicates.</td><td>Preserve match rows and recording identity separately. Never split the same video between training and testing.</td></tr><tr><td>Playlists need expansion</td><td>28 rows include a playlist parameter; one is a playlist-only URL. This audit keys video links by their primary video ID.</td><td>317 rows is not the number of available matches or recordings. Playlist enumeration remains future ingestion work.</td></tr><tr><td>YouTube sample accessible</td><td>Metadata and image frames retrieved for all eight selected sources.</td><td>This verifies those eight only, not every link in the catalogue.</td></tr><tr><td>One Drive probe blocked</td><td>The Wetzikon CAN–ITA file returned HTTP 401 to an unauthenticated request.</td><td>That file needs an authorised access path before auditing. The other Drive files were not checked.</td></tr><tr><td>Rock Channel unresolved</td><td>The gold-match page returned HTTP 200, but page retrieval did not verify playback or expose usable media to this audit.</td><td>Do not count the page as accessible video. The YouTube GSOC source was inspected separately.</td></tr><tr><td>Inconsistent metadata fields</td><td>Source labels include “Us”, “US”, “MD” and “4s”; event spellings vary. One row explicitly says “not available”.</td><td>Preserve original values; normalise source, format and event into separate fields rather than interpreting the column uniformly.</td></tr></tbody></table></div><p class="mini">Normalised primary targets: 276 YouTube video IDs, 10 Drive files, 2 Rock Channel pages, 1 playlist-only URL and 1 missing marker. These are catalogue counts, not independently confirmed playable videos. <a href="catalogue-summary.json">Full catalogue audit JSON →</a></p></section>
<section id="plan"><div class="section-head"><span class="number">04</span><h2>What I would build next.</h2></div><p class="intro">Start with a complete video workflow on customer-style footage. Use a broadcast control to distinguish geometry problems from the harder split-screen reconstruction problems.</p><div class="architecture">Upload <span>→</span> identify panels &amp; view changes <span>→</span> associate sheet / end / match <span>→</span> calibrate each view <span>→</span> detect and follow stones <span>→</span> select settled states <span>→</span> reconstruct a timeline with explicit gaps</div><div class="roadmap"><article><h3>First customer-style case</h3><p>2024 Canada–Korea: one catalogue match, two recurring views and 1080p. Build panel selection, active-end handling and per-view calibration before attempting whole-game state claims.</p></article><article><h3>Geometric control</h3><p>Beijing China–Canada: use clear overhead candidates to establish a detector/calibration baseline. Report this separately so easier broadcast views do not conceal customer-footage failures.</p></article><article><h3>Second family</h3><p>Leduc: support overhead insets without double-counting stones. Test whether the insets can supply useful house coordinates and how wider views contribute guard coverage.</p></article><article><h3>Stress cases</h3><p>480p team recordings, multiple sheets and GSOC identity conflicts. Keep failures visible and measure how much video requires review. Do not label a partial house as a complete board.</p></article></div><div class="note"><strong>These eight are now development/audit examples.</strong> I have inspected them, so they should not be presented as an untouched final test set. Reserve separate recordings—and preferably an entire event/camera setup—for final evaluation. Keep all panels, clips and catalogue aliases of each recording in the same partition.</div><h3>Measure usefulness, not just detection accuracy.</h3><ul class="checklist"><li><strong>Board coverage:</strong> fraction of independently labelled post-shot states reconstructed, with flagged gaps included in the denominator.</li><li><strong>State accuracy:</strong> missed/extra stones, colour or team errors, position error, and complete-board correctness. Report these separately by footage family.</li><li><strong>Temporal correctness:</strong> shot-boundary errors, incorrect active-end selection, camera cuts and mistaken merging of observations.</li><li><strong>Customer effort:</strong> review/correction time per hour of footage, processing time and failure recovery.</li><li><strong>Identity integrity:</strong> wrong match/sheet assignments should be reported explicitly, not hidden inside average coordinate error.</li></ul><p>The remaining customer decision is which output matters first—post-shot board timelines, searchable clips, or a specific analysis workflow—and what coverage/review burden is acceptable. This audit establishes the input challenges; it does not invent acceptance thresholds on the customer's behalf.</p><p><strong>Rust implication:</strong> typestate is useful at boundaries such as <code>UnassignedView → SheetAssociatedView</code> and <code>PartialObservation → ValidatedSnapshot</code>. Runtime evidence must justify those transitions. The footage findings strengthen the case for a typed domain core, not for an immediate physics-engine rewrite.</p></section>
<section id="method"><div class="section-head"><span class="number">05</span><h2>Method, limits and reproducibility.</h2></div><p>Selected eight recordings deliberately to span years, source labels, training/competition, single/shared catalogue links and variants. This is a purposive reconnaissance sample, not a random estimate of catalogue-wide difficulty. For each video, requested frames at 8%, 20%, 32%, 44%, 56%, 68%, 80% and 92% of its reported duration.</p><p>Frames were extracted from direct AVC media, selecting the highest offered resolution up to 1080p. No full-match download was required. One transient frame-fetch timeout was retried successfully: all 64 systematic frames are present. Four additional 12-second windows were sampled at one frame per two seconds, yielding 24 temporal frames. These probes were selected after the initial visual inspection.</p><p>Timestamps identify requested source positions, not independently verified exact frame indices. Sparse samples can reveal cuts, motion, panels and occlusion; they cannot prove continuous coverage, camera synchronisation, centimetre accuracy, or reconstruction of every delivery. No detector, calibration benchmark or full-match reconstruction was run in this audit. Findings are AI visual assessments and need human review before becoming ground-truth labels.</p><p>Frames remain local research evidence with source attribution. Source owners retain rights to the footage; the catalogue and these local downloads do not establish commercial reuse permissions. Nothing was published or changed in the spreadsheet.</p><div class="grid"><article class="card"><h3>Evidence files</h3><div class="links"><a href="catalogue-sample.json">Selected recordings</a><a href="frame-manifest.json">Frame manifest</a><a href="temporal-manifest.json">Temporal manifest</a><a href="observations.json">Visual findings</a><a href="source-access.json">Access probes</a><a href="../sources/provided-video-catalogue.csv">Clean catalogue</a></div></article><article class="card"><h3>Continue exploring</h3><div class="links"><a href="https://docs.google.com/spreadsheets/d/18YT5BgGA98R0RzNPDFg7jGCfuVBFlA0JEOi8oEEHiZw/edit?gid=0">Original spreadsheet ↗</a><a href="../curling-landscape.html">Technology landscape →</a><a href="../../feasibility/report.html">Earlier calibration pilot →</a><a href="README.md">Reproduction instructions →</a></div></article></div></section></main><footer class="wrap footer"><div>Curling footage audit / Local evidence package<br>All qualitative judgements are limited to the samples described above.</div><button class="print" onclick="window.print()">Print / save PDF</button></footer><script>document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{let count=0;document.querySelectorAll('.record').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.family!==button.dataset.filter;if(!card.hidden)count++});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.getElementById('filter-status').textContent=`Showing ${count} recording${count===1?'':'s'}`;}));</script></body></html>"""
(ROOT / "report.html").write_text(body)
print(ROOT / "report.html")
